.main-column { display: flex; min-width: 0; min-height: 0; flex-direction: column; background: #fff; }
.topbar { display: flex; flex: 0 0 62px; align-items: center; justify-content: space-between; gap: 12px; padding: 0 25px; border-bottom: 1px solid #ededee; }
.breadcrumb { display: flex; align-items: center; gap: 10px; min-width: 0; color: #a1a1aa; font-size: 11px; }
.breadcrumb strong { overflow: hidden; color: #3f3f46; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.breadcrumb-slash { color: #d4d4d8; }
.topbar-actions { display: flex; align-items: center; gap: 10px; }
.member-stack { display: flex; align-items: center; padding-left: 5px; }
.member-avatar, .member-more, .tiny-avatar { display: grid; flex: 0 0 auto; place-items: center; border: 2px solid #fff; border-radius: 50%; font-size: 8px; font-weight: 700; }
.member-avatar { width: 26px; height: 26px; margin-left: -5px; }
