.topbar-divider { width: 1px; height: 20px; background: #e4e4e7; }
.avatar-self { width: 27px; height: 27px; cursor: pointer; }
.transcript-toggle { display: none; }

.board-scroll { flex: 1; min-height: 0; overflow-y: auto; background-color: #fff; background-image: radial-gradient(#ececee 0.7px, transparent 0.7px); background-position: -4px -4px; background-size: 22px 22px; }
.board-content { max-width: 930px; margin: 0 auto; padding: 43px 38px 34px; }
.board-heading-row { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin-bottom: 37px; animation: enter 420ms both ease-out; }
.eyebrow { display: flex; align-items: center; gap: 7px; margin-bottom: 11px; color: #85858d; font-size: 9px; font-weight: 700; letter-spacing: 0.075em; }
.live-dot { width: 6px; height: 6px; background: #18181b; box-shadow: 0 0 0 3px #e4e4e7; }
.eyebrow-divider { color: #d4d4d8; }
.board-heading-row h1 { margin: 0; color: #18181b; font-family: 'Space Grotesk', sans-serif; font-size: 31px; font-weight: 600; line-height: 1.12; letter-spacing: 0; }
