.outline-button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 10px; color: #52525b; background: #fff; border: 1px solid #e4e4e7; border-radius: 6px; cursor: pointer; font-size: 10px; font-weight: 600; transition: color 140ms ease, border-color 140ms ease, background 140ms ease; }
.outline-button:hover { color: #18181b; background: #fafafa; border-color: #a1a1aa; }
.board-options { flex: 0 0 auto; margin-bottom: 2px; }
