.idea-count { display: grid; min-width: 19px; height: 19px; place-items: center; padding: 0 5px; color: #71717a; background: #f4f4f5; border-radius: 5px; font-size: 9px; font-weight: 600; }
.text-button { display: inline-flex; align-items: center; gap: 5px; padding: 4px 0; color: #71717a; background: transparent; border: 0; cursor: pointer; font-size: 10px; }
.text-button:hover { color: #18181b; }

.idea-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: stretch; gap: 14px; }
.idea-card { min-width: 0; overflow: hidden; background: #fff; border: 1px solid #e4e4e7; border-radius: 8px; cursor: pointer; box-shadow: 0 1px 2px #18181b08; transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease; animation: enter 520ms both ease-out; }
.idea-card:nth-child(2) { animation-delay: 60ms; }
