.idea-art { position: relative; display: grid; height: 136px; place-items: center; overflow: hidden; background-color: #f4f4f5; border-bottom: 1px solid #e4e4e7; }
.art-index { position: absolute; top: 12px; left: 13px; z-index: 1; color: #71717a; font-size: 8px; font-weight: 700; letter-spacing: 0.1em; }
.save-idea { position: absolute; z-index: 2; top: 8px; right: 8px; display: grid; width: 28px; height: 28px; place-items: center; color: #71717a; background: #ffffffb8; border: 1px solid #ffffff; border-radius: 6px; cursor: pointer; opacity: 0; transition: opacity 140ms ease, color 140ms ease, background 140ms ease; }
.idea-card:hover .save-idea, .save-idea:focus-visible, .save-idea.saved { opacity: 1; }
.save-idea:hover, .save-idea.saved { color: #18181b; background: #fff; }
.art-orbit { background-image: linear-gradient(135deg, #f4f4f5 0%, #e8e8ea 58%, #f7f7f8 100%); }
.orbit-shape { position: relative; display: block; width: 192px; height: 112px; border: 1px solid #b7b7bd; border-radius: 50%; transform: rotate(-20deg); }
.orbit-shape::before, .orbit-shape::after { position: absolute; inset: 12px -13px; border: 1px solid #cacacf; border-radius: 50%; content: ''; transform: rotate(32deg); }
.orbit-shape::after { inset: -13px 35px; border-color: #d1d1d5; transform: rotate(-42deg); }
.orbit-shape span { position: absolute; z-index: 1; width: 11px; height: 11px; background: #343439; border: 3px solid #f1f1f2; border-radius: 50%; }
.orbit-shape span:nth-child(1) { top: 8px; left: 34px; }
.orbit-shape span:nth-child(2) { right: 25px; bottom: 10px; width: 8px; height: 8px; }
.orbit-shape span:nth-child(3) { top: 38px; left: 94px; width: 17px; height: 17px; background: #fff; border-color: #a1a1aa; }
.art-grid { background-color: #f6f6f7; background-image: linear-gradient(#dedee1 1px, transparent 1px), linear-gradient(90deg, #dedee1 1px, transparent 1px); background-position: center; background-size: 24px 24px; }
.grid-shape { display: grid; width: 148px; height: 90px; grid-template-columns: repeat(4, 1fr); gap: 7px; padding: 10px; background: #fff; border: 1px solid #d4d4d8; border-radius: 6px; box-shadow: 0 8px 18px #18181b0a; transform: rotate(-5deg); }
.grid-shape i { border: 1px solid #d4d4d8; border-radius: 3px; background-image: linear-gradient(135deg, transparent 48%, #b8b8bd 49%, #b8b8bd 51%, transparent 52%); }
.grid-shape i:nth-child(2) { background-color: #e4e4e7; }
.grid-shape i:nth-child(3) { background-color: #fafafa; background-image: radial-gradient(#a1a1aa 1px, transparent 1px); background-size: 6px 6px; }
.grid-shape i:nth-child(4) { background: #d4d4d8; }
.art-signal { background: repeating-linear-gradient(0deg, #f4f4f5, #f4f4f5 13px, #ececee 14px); }
.signal-shape { display: flex; align-items: center; justify-content: center; gap: 8px; width: 172px; height: 82px; background: #fff; border: 1px solid #d4d4d8; border-radius: 6px; box-shadow: 0 8px 20px #18181b0c; transform: rotate(3deg); }
.signal-shape i { width: 18px; height: 18px; background: #343439; border-radius: 50%; }
.signal-shape i:nth-child(2), .signal-shape i:nth-child(4) { width: 8px; height: 8px; background: #a1a1aa; }
.signal-shape i:nth-child(3) { width: 34px; height: 34px; background: #e4e4e7; border: 1px solid #a1a1aa; }

.idea-card-body { padding: 12px 13px 11px; }
.idea-card-topline { display: flex; align-items: center; justify-content: space-between; min-height: 25px; }
.idea-tag { padding: 3px 6px; color: #71717a; background: #f4f4f5; border-radius: 4px; font-size: 8px; font-weight: 600; }
.idea-card h3 { margin: 9px 0 6px; color: #27272a; font-family: 'Space Grotesk', sans-serif; font-size: 15px; font-weight: 600; line-height: 1.25; }
.idea-card-body > p { min-height: 48px; margin: 0; color: #71717a; font-size: 10px; line-height: 1.6; }
.idea-card-footer { display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 12px; padding-top: 10px; border-top: 1px solid #f0f0f1; }
.idea-authors { display: flex; align-items: center; min-width: 0; }
.tiny-avatar { width: 21px; height: 21px; margin-right: -5px; font-size: 7px; }
.author-label { overflow: hidden; margin-left: 10px; color: #a1a1aa; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.vote-button { display: flex; align-items: center; gap: 4px; height: 26px; padding: 0 6px; color: #71717a; background: transparent; border: 1px solid transparent; border-radius: 5px; cursor: pointer; font-size: 9px; }
.vote-button:hover { color: #18181b; background: #f4f4f5; border-color: #e4e4e7; }
.vote-arrow { transform: rotate(180deg); }
.add-idea-card { display: flex; min-height: 315px; flex-direction: column; align-items: center; justify-content: center; gap: 8px; padding: 20px; color: #71717a; background: #ffffffa6; border: 1px dashed #d4d4d8; border-radius: 8px; cursor: pointer; transition: background 140ms ease, border-color 140ms ease; animation: enter 560ms 180ms both ease-out; }
.add-idea-card:hover { background: #fff; border-color: #85858d; }
.add-idea-icon { display: grid; width: 34px; height: 34px; place-items: center; color: #52525b; background: #f4f4f5; border: 1px solid #e4e4e7; border-radius: 8px; }
.add-idea-card strong { color: #3f3f46; font-size: 11px; font-weight: 600; }
.add-idea-card > span:last-child { color: #a1a1aa; font-size: 9px; text-align: center; }
.activity-note { display: flex; align-items: center; gap: 8px; margin-top: 26px; padding: 10px 11px; color: #71717a; background: #ffffffb8; border: 1px solid #e4e4e7; border-radius: 6px; font-size: 9px; }
.activity-note > svg { color: #52525b; }
.activity-note > span { flex: 1; }
.activity-note button { display: grid; width: 22px; height: 22px; place-items: center; color: #a1a1aa; background: transparent; border: 0; cursor: pointer; }
.empty-board { display: grid; min-height: 320px; place-content: center; justify-items: center; gap: 10px; color: #a1a1aa; background: #ffffffbd; border: 1px dashed #d4d4d8; border-radius: 8px; text-align: center; }
.empty-board-icon { display: grid; width: 44px; height: 44px; place-items: center; color: #52525b; background: #f4f4f5; border-radius: 50%; }
.empty-board strong { color: #27272a; font-size: 13px; }
.empty-board > span:nth-of-type(2) { font-size: 10px; }
.empty-board .outline-button { margin-top: 5px; }

.recording-dock { display: flex; flex: 0 0 75px; align-items: center; gap: 17px; margin: 0 19px 14px; padding: 0 13px; background: #fff; border: 1px solid #e4e4e7; border-radius: 8px; box-shadow: 0 3px 12px #18181b0a; }
.recording-status { display: flex; flex: 0 0 113px; align-items: center; gap: 9px; }
.recording-indicator { display: grid; width: 28px; height: 28px; place-items: center; background: #f4f4f5; border-radius: 50%; }
.recording-indicator > span { width: 8px; height: 8px; background: #27272a; border-radius: 50%; }
.recording-indicator.recording > span { animation: record-pulse 1.8s infinite; }
.recording-indicator.paused > span { background: #a1a1aa; }
.recording-indicator.stopped > span { width: 7px; height: 7px; border-radius: 1px; }
.recording-copy { display: grid; gap: 2px; }
.recording-copy strong { color: #3f3f46; font-size: 10px; font-weight: 600; }
.recording-copy span { color: #a1a1aa; font-size: 9px; }
.waveform { display: flex; flex: 1; align-items: center; justify-content: center; gap: 3px; min-width: 40px; height: 40px; overflow: hidden; }
.waveform i { width: 2px; height: var(--bar-height); flex: 0 0 auto; background: #71717a; border-radius: 3px; animation: wave 780ms ease-in-out infinite alternate; }
.waveform i:nth-child(3n) { animation-delay: -240ms; }
.waveform i:nth-child(4n) { animation-delay: -510ms; }
.waveform.muted i { height: 5px; animation: none; background: #d4d4d8; }
.recording-time { display: inline-flex; flex: 0 0 auto; align-items: center; gap: 5px; color: #71717a; font-variant-numeric: tabular-nums; font-size: 10px; }
.record-control { display: grid; flex: 0 0 auto; width: 33px; height: 33px; place-items: center; color: #52525b; background: #fff; border: 1px solid #e4e4e7; border-radius: 7px; cursor: pointer; transition: color 140ms ease, background 140ms ease, border-color 140ms ease; }
.record-control:hover { color: #18181b; background: #f4f4f5; border-color: #d4d4d8; }
.stop-control svg { width: 11px; height: 11px; }
.primary-control { display: flex; width: auto; gap: 6px; padding: 0 9px; color: #fafafa; background: #18181b; border-color: #18181b; font-size: 9px; font-weight: 600; }
.primary-control:hover { color: #fff; background: #303034; border-color: #303034; }
.record-more { margin-left: -9px; }

.transcript-sidebar { display: flex; min-width: 0; flex-direction: column; background: #fff; border-left: 1px solid var(--border); }
.transcript-header { display: flex; flex: 0 0 72px; align-items: center; justify-content: space-between; gap: 8px; padding: 0 18px; border-bottom: 1px solid #ededee; }
.transcript-title-row { display: flex; align-items: center; gap: 5px; }
.transcript-header h2 { margin: 0; color: #27272a; font-family: 'Space Grotesk', sans-serif; font-size: 14px; font-weight: 600; }
.transcript-header p { display: flex; align-items: center; gap: 6px; margin: 4px 0 0; color: #a1a1aa; font-size: 9px; }
.transcript-live { width: 6px; height: 6px; background: #a1a1aa; border-radius: 50%; }
.transcript-live.is-live { background: #27272a; box-shadow: 0 0 0 3px #e4e4e7; }
.transcript-tools { display: flex; flex: 0 0 46px; align-items: center; justify-content: space-between; padding: 0 14px; border-bottom: 1px solid #f0f0f1; }
.transcript-filter { display: inline-flex; align-items: center; gap: 7px; height: 27px; padding: 0 7px; color: #52525b; background: #fff; border: 1px solid #e4e4e7; border-radius: 5px; cursor: pointer; font-size: 9px; }
.transcript-filter:hover { background: #fafafa; }
.transcript-feed { flex: 1; min-height: 0; overflow-y: auto; padding: 18px 15px; }
.transcript-date { display: flex; align-items: center; gap: 9px; margin: 0 0 19px; color: #a1a1aa; font-size: 8px; font-weight: 700; letter-spacing: 0.1em; }
.transcript-date span { height: 1px; flex: 1; background: #ededee; }
.transcript-line { display: flex; gap: 9px; margin-bottom: 19px; animation: enter 380ms both ease-out; }
.speaker-avatar { display: grid; width: 25px; height: 25px; flex: 0 0 auto; place-items: center; border-radius: 50%; font-size: 7px; font-weight: 700; }
.transcript-line-content { min-width: 0; flex: 1; }
.speaker-meta { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 2px 0 5px; }
.speaker-meta strong { color: #3f3f46; font-size: 9px; font-weight: 700; }
.speaker-meta time { color: #a1a1aa; font-size: 8px; font-variant-numeric: tabular-nums; }
.transcript-line-content p { color: #71717a; font-size: 10px; line-height: 1.62; }
.currently-speaking .transcript-line-content p { color: #3f3f46; }
.transcript-capture { display: flex; align-items: center; gap: 8px; margin: 6px 0 0 34px; color: #a1a1aa; font-size: 9px; }
.capture-avatar { display: grid; width: 21px; height: 21px; place-items: center; color: #71717a; background: #f4f4f5; border-radius: 50%; font-size: 12px; }
.capture-pulse { width: 5px; height: 5px; background: #71717a; border-radius: 50%; animation: record-pulse 1.8s infinite; }
.transcript-footer { display: grid; gap: 9px; padding: 12px 15px 14px; border-top: 1px solid #ededee; }
.transcript-export { display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 8px; color: #52525b; background: #fff; border: 1px solid #e4e4e7; border-radius: 6px; cursor: pointer; font-size: 9px; }
.transcript-export:hover { color: #18181b; background: #fafafa; }
.transcript-export span { flex: 1; text-align: left; }
.transcript-private { color: #a1a1aa; font-size: 8px; text-align: center; }
.mobile-close, .mobile-scrim { display: none; }

@keyframes enter { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: translateY(0); } }
@keyframes record-pulse { 0%, 100% { box-shadow: 0 0 0 0 #27272a33; } 50% { box-shadow: 0 0 0 5px #27272a00; } }
@keyframes wave { from { transform: scaleY(0.68); } to { transform: scaleY(1); } }

@media (max-width: 1160px) {
  .app-shell { grid-template-columns: 220px minmax(390px, 1fr) 286px; }
  .board-content { padding-right: 28px; padding-left: 28px; }
  .recording-dock { gap: 12px; margin-right: 12px; margin-left: 12px; }
  .recording-status { flex-basis: 102px; }
  .waveform { gap: 2px; }
}

@media (max-width: 980px) {
  .app-shell { grid-template-columns: 224px minmax(0, 1fr); }
  .transcript-sidebar { position: fixed; z-index: 21; top: 0; right: 0; bottom: 0; width: min(360px, calc(100vw - 70px)); box-shadow: -12px 0 32px #18181b12; transform: translateX(105%); transition: transform 220ms ease; }
  .transcript-sidebar.mobile-open { transform: translateX(0); }
  .mobile-close, .transcript-toggle { display: inline-grid; }
  .mobile-scrim { position: fixed; z-index: 20; inset: 0; display: block; background: #18181b55; border: 0; }
}

@media (max-width: 640px) {
  .app-shell { grid-template-columns: 58px minmax(0, 1fr); min-height: 560px; }
  .session-sidebar { align-items: center; padding: 13px 6px 9px; }
  .wordmark { padding: 4px 0 19px; }
  .wordmark > span:last-child, .new-session-button > span, .session-search, .nav-section-heading, .nav-link > span, .session-group-title, .session-name, .active-dot, .profile-copy, .profile-row > svg { display: none; }
  .new-session-button { justify-content: center; width: 36px; padding: 0; }
  .nav-link, .session-item { justify-content: center; width: 36px; height: 36px; padding: 0; }
  .session-list-area { width: 100%; margin-top: 3px; }
